function isListableLimit(limit: unknown): boolean {
  return typeof limit === 'number' && Number.isInteger(limit) && limit >= 0;
}

function isCursorSessionId(sessionId: unknown): boolean {
  return typeof sessionId === 'string' && sessionId.length > 0 && sessionId.length <= MAX_CURSOR_SESSION_ID;
}

// Why the frame's `before` is not a cursor, or undefined when it is one: named answers keep the caller's checks flat.
function cursorError(before: unknown): string | undefined {
  if (typeof before !== 'object' || before === null) {
    return 'list_sessions before, when present, must be an object with updatedAt and sessionId';
  }
  const {updatedAt, sessionId} = before as Record<string, unknown>;
  if (typeof updatedAt !== 'string' && typeof updatedAt !== 'number') {
    return 'list_sessions before.updatedAt must be an ISO string or an epoch number';
  }
  if (!Number.isFinite(new Date(updatedAt).getTime())) {
    return 'list_sessions before.updatedAt must parse as a date';
  }
  if (!isCursorSessionId(sessionId)) {
    return `list_sessions before.sessionId must be 1-${MAX_CURSOR_SESSION_ID} characters`;
  }
  return undefined;
}

// Static, configless: the frame is accepted whether or not a feature flag would answer it (specs/hal-engine-conversation-list/spec.md).
function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
  const {limit, before} = message;
  if (limit !== undefined && !isListableLimit(limit)) {
    return {valid: false, error: 'list_sessions limit, when present, must be a non-negative integer'};
  }

  const problem = before === undefined ? undefined : cursorError(before);
  if (problem !== undefined) {
    return {valid: false, error: problem};
  }

  // Built from picked fields alone, so an unknown field - a smuggled userId included - is dropped rather than forwarded.
  return {
    valid: true,
    data: {
      type: 'list_sessions',
      ...(limit !== undefined ? {limit} : {}),
      ...(before !== undefined ? {before: before as ListSessionsMessage['before']} : {}),
    },
  };
}

