import type {IncomingMessage, ListSessionsMessage} from '../../types/messages.js';

const MAX_CONTENT_LENGTH = 10000;
const MAX_CURSOR_SESSION_ID = 128;

interface ValidationSuccess {
  valid: true;
  data: IncomingMessage;
}

interface ValidationFailure {
  valid: false;
  error: string;
}

export type ValidationResult = ValidationSuccess | ValidationFailure;

type MessageValidator = (message: Record<string, unknown>) => ValidationResult;

// Keyed by the frame's type, so a new frame is a new entry and no dispatch site reopens.
const validators: Record<string, MessageValidator> = {
  user_message: validateUserMessage,
  ping: validatePingMessage,
  list_sessions: validateListSessionsMessage,
};

export function validateMessage(payload: unknown): ValidationResult {
  if (typeof payload !== 'object' || payload === null) {
    return {valid: false, error: 'Message must be an object'};
  }

  const message = payload as Record<string, unknown>;

  if (typeof message.type !== 'string') {
    return {valid: false, error: 'Message must have a type field'};
  }

  const validate = validators[message.type];
  return validate ? validate(message) : {valid: false, error: `Unknown message type: ${message.type}`};
}

function validateUserMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.content !== 'string') {
    return {valid: false, error: 'user_message must have content string'};
  }

  const trimmed = message.content.trim();

  if (trimmed.length === 0) {
    return {valid: false, error: 'Message content cannot be empty'};
  }

  if (message.content.length > MAX_CONTENT_LENGTH) {
    return {valid: false, error: `Message content too long (max ${MAX_CONTENT_LENGTH} chars)`};
  }

  return {
    valid: true,
    data: {
      type: 'user_message',
      content: message.content,
    },
  };
}

function validatePingMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.timestamp !== 'number') {
    return {valid: false, error: 'ping must have timestamp number'};
  }

  return {
    valid: true,
    data: {
      type: 'ping',
      timestamp: message.timestamp,
    },
  };
}

// Static, configless: the frame is accepted whether or not a feature flag would answer it (specs/hal-engine-conversation-list/spec.md).
function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
  const limit = message.limit;
  if (limit !== undefined && (typeof limit !== 'number' || !Number.isInteger(limit) || limit < 0)) {
    return {valid: false, error: 'list_sessions limit, when present, must be a non-negative integer'};
  }

  let before: ListSessionsMessage['before'];
  if (message.before !== undefined) {
    if (typeof message.before !== 'object' || message.before === null) {
      return {
        valid: false,
        error: 'list_sessions before, when present, must be an object with updatedAt and sessionId',
      };
    }
    const cursor = message.before as Record<string, unknown>;
    const {updatedAt, sessionId} = cursor;
    if (typeof updatedAt !== 'string' && typeof updatedAt !== 'number') {
      return {valid: false, error: 'list_sessions before.updatedAt must be an ISO string or an epoch number'};
    }
    if (!Number.isFinite(new Date(updatedAt).getTime())) {
      return {valid: false, error: 'list_sessions before.updatedAt must parse as a date'};
    }
    if (typeof sessionId !== 'string' || sessionId.length === 0 || sessionId.length > MAX_CURSOR_SESSION_ID) {
      return {valid: false, error: `list_sessions before.sessionId must be 1-${MAX_CURSOR_SESSION_ID} characters`};
    }
    before = {updatedAt, sessionId};
  }

  // Built from picked fields alone, so an unknown field - a smuggled userId included - is dropped rather than forwarded.
  return {
    valid: true,
    data: {
      type: 'list_sessions',
      ...(limit !== undefined ? {limit} : {}),
      ...(before !== undefined ? {before} : {}),
    },
  };
}

