import {WebSocket} from 'ws';
import {createMessageHandler} from './messageHandler.js';
import type {ChatOrchestrator} from '../../orchestration/chatOrchestrator.js';
import type {ChatSession} from '../../types/session.js';
import type {MessageChunk} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import type {SessionCursor, SessionListOptions, SessionStore, SessionSummary} from '../../types/sessionStore.js';
import {InMemorySessionStore} from '../../infrastructure/stores/inMemorySessionStore.js';
import {deferred, eventually} from '../wsTestSupport.js';

// The handler's own decisions, apart from the wire the acceptance suite already exercises over a real socket.

const harness = (store: SessionStore, orchestrator: ChatOrchestrator) => {
  const sent: OutgoingMessage[] = [];
  const ws = {send: (raw: string) => sent.push(JSON.parse(raw) as OutgoingMessage)} as unknown as WebSocket;
  const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
  // One argument per facet: the store arrives beside the orchestrator, the way createServer holds both.
  const handle = createMessageHandler(orchestrator, store);
  return {
    sent,
    ask: (frame: unknown) => handle(ws, session, frame),
  };
};

describe('the list_sessions frame handler', () => {
  it("answers the session user's own list as ISO strings, forwarding limit and before and ignoring the frame's userId", async () => {
    const before: SessionCursor = {updatedAt: '2026-01-01T00:05:00.000Z', sessionId: 's3'};
    const summaries: SessionSummary[] = [
      {
        sessionId: 's2',
        createdAt: new Date('2026-01-01T00:00:00.000Z'),
        updatedAt: new Date('2026-01-01T00:02:00.000Z'),
        entryCount: 4,
      },
    ];
    const seen: Array<{userId: string | number; options?: SessionListOptions}> = [];
    const h = harness(
      {
        listFor: (userId: string | number, options?: SessionListOptions) => {
          seen.push({userId, options});
          return summaries;
        },
      } as unknown as SessionStore,
      {} as ChatOrchestrator
    );

    await h.ask({type: 'list_sessions', limit: 10, before, userId: 'u2'});

    expect({seen, sent: h.sent}).toEqual({
      seen: [{userId: 'u1', options: {limit: 10, before}}],
      sent: [
        {
          type: 'session_list',
          sessions: [
            {
              sessionId: 's2',
              createdAt: '2026-01-01T00:00:00.000Z',
              updatedAt: '2026-01-01T00:02:00.000Z',
              entryCount: 4,
            },
          ],
        },
      ],
    });
  });

  // Held open mid-answer: the turn's lock is still taken the whole time the list is asked, so only the dispatch decides.
  it('answers a list_sessions asked mid-turn before that turn commits or ends, without waiting on the lock', async () => {
    const hold = deferred();
    const midAnswer: ChatOrchestrator = {
      processMessage: async () => 'hi',
      async *processMessageStream(): AsyncGenerator<MessageChunk> {
        yield {type: 'text', text: 'half'};
        await hold.until;
        yield {type: 'stop', stopReason: 'end_turn'};
      },
    };
    const h = harness(new InMemorySessionStore(), midAnswer);

    const turn = h.ask({type: 'user_message', content: 'hello'});
    // The user entry and the open answer are out: the turn holds the lock from here until release.
    await eventually(() => h.sent.length >= 3);
    const answered = await Promise.race([
      h.ask({type: 'list_sessions'}).then(() => true),
      new Promise<boolean>(resolve => setTimeout(() => resolve(false), 200)),
    ]);
    hold.release();
    await turn;

    expect({answeredWhileStreaming: answered, frames: h.sent.map(frame => frame.type)}).toEqual({
      answeredWhileStreaming: true,
      frames: ['entry_upsert', 'entry_upsert', 'entry_delta', 'session_list', 'entry_commit', 'stream_end'],
    });
  });
});
